15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(locality(owner))")
29	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
32	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
33	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's age band from the birth date, computed as the owner's age on the
39	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
40	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
41	     * date is absent, so an owner created without a birth date carries no age band.
42	     */
43	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
44	        java.time.LocalDate birthDate = owner.getBirthDate();
45	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
46	        if (birthDate == null || registrationDate == null) {
47	            return null;
48	        }
49	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
50	        if (age < 18) {
51	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
52	        }
53	        if (age < 65) {
54	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
55	        }
56	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
57	    }
58	
59	    /**
60	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
61	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
62	     */
63	    default Integer checkDigit(Owner owner) {
64	        String customerCode = owner.getCustomerCode();
65	        if (customerCode == null) {
66	            return null;
67	        }
68	        int sum = 0;
69	        boolean dbl = true;
70	        for (int i = customerCode.length() - 1; i >= 0; i--) {
71	            char c = customerCode.charAt(i);
72	            if (c < '0' || c > '9') {
73	                continue;
74	            }
75	            int d = c - '0';
76	            if (dbl) {
77	                d *= 2;
78	                if (d > 9) {
79	                    d -= 9;
80	                }
81	            }
82	            sum += d;
83	            dbl = !dbl;
84	        }
85	        return (10 - (sum % 10)) % 10;
86	    }
87	
88	    /**
89	     * Derives the owner's duplicate-detection identity key, formatted
90	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The email and household-id segments are
91	     * empty when the respective field is absent. The telephone and email are already stored in their
92	     * normalized (E.164 / lower-cased) form, so the stored values are used directly. This is the single
93	     * key against which owner duplicates are detected: two owners collide only when their whole keys
94	     * match.
95	     */
96	    default String identityKey(Owner owner) {
97	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
98	        String email = owner.getEmail() == null ? "" : owner.getEmail();
99	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
100	        return telephone + "|" + email + "|" + householdId;
101	    }
102	
103	    /**
104	     * Fixed city-to-region table used to derive an owner's locality.
105	     */
106	    java.util.Map<String, String> CITY_REGION =
107	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
108	
109	    /**
110	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
111	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
112	     */
113	    java.util.Map<String, int[]> REGION_POSTCODES =
114	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
115	
116	    /**
117	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
118	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
119	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
120	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
121	     * {@code "UNKNOWN"} when neither source resolves a region.
122	     */
123	    default String locality(Owner owner) {
124	        String customerCode = owner.getCustomerCode();
125	        if (customerCode != null) {
126	            int dash = customerCode.indexOf('-');
127	            String region = dash >= 0 ? customerCode.substring(0, dash) : customerCode;
128	            if (!region.isEmpty()) {
129	                return region;
130	            }
131	        }
132	        String postcode = owner.getPostcode();
133	        if (postcode != null) {
134	            try {
135	                int value = Integer.parseInt(postcode.trim());
136	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
137	                    int[] range = entry.getValue();
138	                    if (value >= range[0] && value <= range[1]) {
139	                        return entry.getKey();
140	                    }
141	                }
142	            }
143	            catch (NumberFormatException ex) {
144	                // Not a numeric postcode; fall back to the city table below.
145	            }
146	        }
147	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
148	    }
149	
150	    /**
151	     * Fixed region-to-timezone table used to derive an owner's timezone as an IANA name.
152	     */
153	    java.util.Map<String, String> REGION_TIMEZONE =
154	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
155	
156	    /**
157	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
158	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
159	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}. Returns {@code null} when
160	     * the region does not resolve to a known timezone (e.g. the locality is {@code "UNKNOWN"}).
161	     */
162	    default String timezone(Owner owner) {
163	        return REGION_TIMEZONE.get(locality(owner));
164	    }
165	
166	    /**
167	     * Known E.164 country calling codes, longest first, used to split a stored E.164 telephone into
168	     * its country code and national digits when formatting {@link #telephoneDisplay(Owner)}.
169	     */
170	    String[] TELEPHONE_COUNTRY_CODES = {"61", "1"};
171	
172	    /**
173	     * Formats the owner's stored E.164 telephone for humans: the country code, a space, then the
174	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
175	     * The country code is recognised from the {@link #TELEPHONE_COUNTRY_CODES} table; when none matches,
176	     * all digits after the {@code '+'} are treated as the national number. Returns {@code null} when the
177	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164 number.
178	     */
179	    default String telephoneDisplay(Owner owner) {
180	        String telephone = owner.getTelephone();
181	        if (telephone == null) {
182	            return null;
183	        }
184	        if (!telephone.startsWith("+")) {
185	            return telephone;
186	        }
187	        String digits = telephone.substring(1);
188	        if (!digits.chars().allMatch(Character::isDigit)) {
189	            return telephone;
190	        }
191	        String countryCode = "";
192	        for (String code : TELEPHONE_COUNTRY_CODES) {
193	            if (digits.startsWith(code) && digits.length() > code.length()) {
194	                countryCode = code;
195	                break;
196	            }
197	        }
198	        String national = digits.substring(countryCode.length());
199	        StringBuilder grouped = new StringBuilder();
200	        for (int i = 0; i < national.length(); i++) {
201	            if (i > 0 && i % 3 == 0) {
202	                grouped.append(' ');
203	            }
204	            grouped.append(national.charAt(i));
205	        }
206	        return "+" + countryCode + " " + grouped;
207	    }
208	
209	    /**
210	     * Derives the owner's preferred contact channel: {@code "EMAIL"} when an email address is
211	     * present (non-blank), otherwise {@code "PHONE"}.
212	     */
213	    default String contactPreference(Owner owner) {
214	        String email = owner.getEmail();
215	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
216	    }
217	
218	    /**
219	     * Computes the owner's membership points. Starts at {@code 0} and adds {@code 2} when an email
220	     * is present, {@code 1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}),
221	     * {@code 2} for a household of {@code 3} or more ({@code householdSize}), and {@code 3} when the
222	     * owner's tenure exceeds {@code 365} days (measured from the {@code registrationDate} to the
223	     * current date).
224	     */
225	    default Integer membershipPoints(Owner owner) {
226	        Integer namesakeCount = owner.getNamesakeCount();
227	        String email = owner.getEmail();
228	        Integer householdSize = owner.getHouseholdSize();
229	        int points = 0;
230	        if (email != null && !email.isBlank()) {
231	            points += 2;
232	        }
233	        if (namesakeCount != null && namesakeCount == 0) {
234	            points += 1;
235	        }
236	        if (householdSize != null && householdSize >= 3) {
237	            points += 2;
238	        }
239	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
240	        boolean hasTenure = registrationDate != null
241	            && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now()) > 365;
242	        if (hasTenure) {
243	            points += 3;
244	        }
245	        return points;
246	    }
247	
248	    /**
249	     * Derives the owner's membership level, a number from 1 to 4, from the owner's
250	     * {@link #membershipPoints(Owner) membership points}: level {@code 1} for {@code 0-1} points,
251	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
252	     */
253	    default Integer membershipLevel(Owner owner) {
254	        int points = membershipPoints(owner);
255	        if (points <= 1) {
256	            return 1;
257	        }
258	        if (points <= 3) {
259	            return 2;
260	        }
261	        if (points <= 5) {
262	            return 3;
263	        }
264	        return 4;
265	    }
266	
267	    /**
268	     * Builds the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where
269	     * {@code YY} is the last two digits of the registration date's year (e.g. {@code "NSW-3F2A1B9C-M26"}).
270	     * Returns {@code null} when the customer code or registration date is absent.
271	     */
272	    default String membershipNumber(Owner owner) {
273	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
274	            return null;
275	        }
276	        int yy = owner.getRegistrationDate().getYear() % 100;
277	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
278	    }
279	
280	    /**
281	     * Builds the owner's salutation: the supplied title and last name joined by a single space
282	     * (e.g. {@code "DR Franklin"}) when a title is present (non-blank), otherwise just the last
283	     * name. Returns {@code null} when the owner has no last name.
284	     */
285	    default String salutation(Owner owner) {
286	        String lastName = owner.getLastName();
287	        String title = owner.getTitle();
288	        if (title == null || title.isBlank()) {
289	            return lastName;
290	        }
291	        return title + " " + lastName;
292	    }
293	
294	    /**
295	     * Builds the owner's initials as the upper-cased first letters of the first and last
296	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
297	     */
298	    default String initials(Owner owner) {
299	        String first = owner.getFirstName();
300	        String last = owner.getLastName();
301	        StringBuilder sb = new StringBuilder();
302	        if (first != null && !first.isEmpty()) {
303	            sb.append(Character.toUpperCase(first.charAt(0))).append('.');
304	        }
305	        if (last != null && !last.isEmpty()) {
306	            sb.append(Character.toUpperCase(last.charAt(0))).append('.');
307	        }
308	        return sb.toString();
309	    }
310	
311	    Owner toOwner(OwnerDto ownerDto);
312	
313	    @Mapping(target = "id", ignore = true)
314	    @Mapping(target = "pets", ignore = true)
315	    Owner toOwner(OwnerFieldsDto ownerDto);
316	
317	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
318	
319	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
320	
321	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
322	        OwnerPageDto ownerPageDto = new OwnerPageDto();
323	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
324	        ownerPageDto.setPage(ownerPage.getNumber());
325	        ownerPageDto.setSize(ownerPage.getSize());
326	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
327	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
328	        return ownerPageDto;
329	    }
330	}
